+package ratpack.session.internal;
+
+import ratpack.api.Nullable;
+import ratpack.session.SessionKey;
+
+import java.io.Serializable;
+
+public class DefaultSessionKey<T> implements SessionKey<T>, Serializable {
+
+  private static final long serialVersionUID = 1;
+
+  private final String name;
+  private final Class<T> type;
+
+  public DefaultSessionKey(String name, Class<T> type) {
+    this.name = name;
+    this.type = type;
+  }
+
+  @Nullable
+  @Override
+  public String getName() {
+    return name;
+  }
+
+  @Override
+  public Class<T> getType() {
+    return type;
+  }
+
+  @Override
+  public boolean equals(Object o) {
+    if (this == o) {
+      return true;
+    }
+    if (o == null || getClass() != o.getClass()) {
+      return false;
+    }
+
+    DefaultSessionKey<?> that = (DefaultSessionKey<?>) o;
+
+    return !(name != null ? !name.equals(that.name) : that.name != null) && !(type != null ? !type.equals(that.type) : that.type != null);
+  }
+
+  @Override
+  public int hashCode() {
+    int result = name != null ? name.hashCode() : 0;
+    result = 31 * result + (type != null ? type.hashCode() : 0);
+    return result;
+  }
+
+  @Override
+  public String toString() {
+    return "SessionKey[name='" + name + '\'' + ", type=" + type + ']';
+  }
+}

