+ *    RatpackServer server = RatpackLauncher.launcher(r -> {
+ *      r.add(MyHandler.class, new MyHandler());
+ *    }).config( c -> {
+ *      c.port(5060);
+ *    }).build(registry -> {
+ *      return registry.get(MyHandler.class);
+ *    });
+ *    server.start();
