+    if (separator == null) {
+      throw new NullPointerException("The 'separator' cannot be null");
+    }
+    if (objects == null) {
+      throw new NullPointerException("The 'objects' cannot be null");
+    }
+
+    boolean first = true;
+    StringBuilder string = new StringBuilder();
+    for (Object object : objects) {
+      if (!first) {
