+
+  StaticAssetsConfig staticAssets
+
+  Closure<?> routingClosure = {}
+  List<Module> modules = []
+
+  Handler<Routing> routingHandler = new Handler<Routing>() {
+    @Override
+    void handle(Routing routing) {
+      Closure clone = DefaultRatpackSpec.this.routingClosure.clone()
